import{_ as n,l as i,o as e,c as s,v as t,p as l,x as r,d as E,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"跨品种价差","description":"","frontmatter":{"title":"跨品种价差","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/intercommodity-spread.md","filePath":"quant/intercommodity-spread.md","lastUpdated":1789023840000}'),h={name:"quant/intercommodity-spread.md"};function B(p,a,c,A,u,_){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="跨品种价差" tabindex="-1">跨品种价差 <a class="header-anchor" href="#跨品种价差" aria-label="Permalink to &quot;跨品种价差&quot;">​</a></h1><div class="epigraph"><p>炼油、压榨与发电把一种商品变成另一种；加工价差是技术约束在期货曲线上的投影，不是两道不相关的随机游走碰巧靠近。</p><footer>—— 仓储与加工的联系见 Working, American Economic Review, 1949；能源加工价差的期货表述见 Geman, Commodities and Commodity Derivatives, 2005</footer></div><p>同一条供应链上的商品，现货被工艺与运输钉在一起：原油进炼厂变成汽油与馏分，大豆压榨成豆油与豆粕，天然气进汽轮机变成电。期货允许把这些约束写成可交易的价差——裂解价差（crack）、压榨价差（crush）、火花价差（spark）。跨品种价差交易的对象不是「两个代码的相关系数」，而是加工利润或替代弹性是否被曲线错误标记。Working 的仓储理论本来说的是同一商品的现货与期货；把它横着读，库存与产能利用率同样约束<strong>相关</strong>商品的相对价格。Gorton 与 Rouwenhorst（2006）把商品当作资产类别时强调横截面分散；本篇反过来：分散之前，先承认哪些品种在实物上不能分散。统计工具可以借用 <a href="/quant/engle-granger">Engle–Granger</a> 与 <a href="/quant/johansen">Johansen</a>，但协整向量应当能翻译成桶、蒲式耳或热值，而不是纯样本内 \\(R^2\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若把 WTI 与 RBOB 汽油当成两只可以任意配比的期货，样本内总能找到一组权重让残差看起来均值回复。样本外炼厂检修、环保规格切换、出口窗口打开，最优权重会跳。问题是给价差一个<strong>实物单位</strong>：典型的 3-2-1 裂解是三桶原油对两桶汽油加一桶取暖油，近似一套简单炼厂的边际产出，而不是回归出来的 beta。压榨价差用一蒲式耳大豆对固定磅数的豆油与豆粕。火花价差用燃料热值与热耗率把天然气换成电。没有单位，统计套利会在「相关的噪声」上过拟合。</p><p>第二层问题是曲线的哪一段。近月裂解反映当下炼厂利润与库存；远月裂解反映产能与需求预期。跨品种还可以跨到期：用近月汽油对远月原油，引入了仓储与展期。本篇默认同一交割月附近的加工价差；把展期叠进去时，应显式拆成加工腿与 <a href="/quant/seasonal-roll">季节性展期</a> 腿。</p><h3 id="替代、联产品与地点" tabindex="-1">替代、联产品与地点 <a class="header-anchor" href="#替代、联产品与地点" aria-label="Permalink to &quot;替代、联产品与地点&quot;">​</a></h3><p>不是所有高相关品种都有加工约束。黄金与白银是替代与投资需求，不是下游配方；WTI 与布伦特是地点与品质价差，约束是航运与管道，不是化学反应。玉米与小麦在饲料上可部分替代，弹性随相对价格变。联产品（豆油与豆粕）还必须满足压榨的物料平衡：不能长期只涨其中一个而大豆与另一个不动。把所有两两相关都叫做跨品种价差，会把宏观风险因子（美元、中国需求）包装成虚假的加工利润。</p><p><span class="marginnote">3-2-1 是教学用的固定配方，真实炼厂有催化裂化、加氢与季节性收率。交易上用固定比例是为了可复制与清算所保证金识别；把回归权重当成「更科学的炼厂」，通常只是把季节与趋势装进 beta。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定价从现货加工利润出发。忽略质量升贴水时，裂解的期货版本是</p> \\[\\mathrm{Crack}_t=2F^{\\mathrm{HO}}(t,T)+3F^{\\mathrm{RB}}(t,T)-6F^{\\mathrm{CL}}(t,T) \\]<p>一类线性组合（系数随合约乘数改写），再除以原油桶数得到美元/桶。压榨、火花同理，火花还要减可变运维并除以热耗率。仓位用合约张数去匹配实物比例，而不是用美元中性——美元中性会在原油暴涨时把炼厂利润的量纲扭曲成「股票对冲」。</p><p>统计上，把价差水平当作候选的协整残差：先按实物权重构造 \\(s_t\\)，再检验 \\(s_t\\) 是否平稳；不要先自由估 beta 再讲故事。若实物权重下 \\(s_t\\) 有单位根，应怀疑约束在样本里断了（页岩油改变了轻质—重质价差、乙醇政策改变了玉米—汽油），而不是立刻改权重。半衰期、入场阈值走 <a href="/quant/ou-spread">OU 价差</a> 与 <a href="/quant/zscore-entry">z-score 入场</a> 的同一套，但止损要按加工利润的经济边界来：裂解长期为负超过可变成本，炼厂会停工，价差有期权式的下限——线性 OU 在边界附近是错的。</p><h3 id="保证金、腿数与执行" tabindex="-1">保证金、腿数与执行 <a class="header-anchor" href="#保证金、腿数与执行" aria-label="Permalink to &quot;保证金、腿数与执行&quot;">​</a></h3><p>三腿以上的价差在交易所常有优惠保证金，因为清算所按组合风险记账。场外或用替代合约拼出来的「合成裂解」没有这一优惠，腿之间的成交时滞会造成瞬时方向暴露。执行应尽量用交易所价差指令或期货转现货（EFP），而不是三笔独立市价。跨市场（ICE 布伦特对 NYMEX 汽油）还要处理交易时段与美元计价是否一致。这些不是微观结构装饰：跨品种策略的夏普往往在回测的结算价上好看，在腿间滑点上消失。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无套利的上界来自产能与仓储。裂解过高，炼厂提高开工、进口成品油，压低成品、抬高原油；过低则停工、累库。约束生效需要时间，所以价差可以在数周内远离历史均值，这与股票配对里「均值回复是统计事实」不同——这里均值回复是产能响应。Working 意义上的库存，对原油、成品油可以朝相反方向走：成品油库存低而原油库存高，正是裂解该强的状态。Gorton、Hayashi 与 Rouwenhorst（2013）对单品种证明便利收益是库存的非线性递减函数；跨品种要把该函数写在<strong>相对库存</strong>上：汽油库存分位减原油库存分位，才是裂解的状态变量。</p><p>火花价差还受电不能经济地大规模储存这一约束：电的现货可以尖峰，天然气相对平滑，近月火花的分布严重右偏。用高斯价差模型去卖电的近月尖峰，是把便利收益的极端值当成普通残差。</p><p><span class="marginnote">凯恩斯—希克斯的正常 backwardation 针对的是单品种期货相对未来现货的溢价。跨品种价差的风险溢价可以来自加工商套保压力（炼厂卖裂解），但实证上应像 Gorton 等人那样，先问相对库存能否预测价差收益，再问 CFTC 持仓是否还有增量。</span></p><h3 id="协整断点就是工艺断点" tabindex="-1">协整断点就是工艺断点 <a class="header-anchor" href="#协整断点就是工艺断点" aria-label="Permalink to &quot;协整断点就是工艺断点&quot;">​</a></h3><p>页岩油使美国轻质原油供给过剩，WTI—布伦特与轻质—重质价差的长期均值移动。乙醇掺混改变玉米与汽油的联立。日本核电重启或欧洲气电替代会改写火花的均值。统计上这是 <a href="/quant/cointegration-break">协整断点</a>；经济上这是约束集合变了。断点之后仍用旧实物权重，只是换了阈值，还算诚实；用样本内重新估的自由权重去「适应」断点，通常是把新制度的前两年噪声当成新均衡。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>跨品种价差不是低风险的统计套利。共同因子（全球增长、美元、风险偏好）可以让所有腿同向跳，实物对冲比在危机里失效——2008 年与 2020 年原油与成品油都出现过交割与仓储极限。保证金优惠在波动上升时会被交易所调整，组合的杠杆被动变化。品质与地点：RBOB 不是所有地区的零售汽油，Henry Hub 不是欧洲 TTF，大商所豆粕不是 CBOT 豆粕。用流动性最好的合约去代理你真正暴露的现货，基差风险应单列，而不是写进「价差的 alpha」。</p><p>不要把黄金—白银、铜—铝与裂解放进同一个因子。前两者是宏观替代与库存周期，后者是加工。可以都交易，但归因、风控与文献引用不应混用。Geman（2005）把能源衍生品写成现货、远期与便利收益的联合系统，是处理加工价差时比单纯协整教科书更贴的框架。</p><p><span class="marginnote">回测若用主连连续价格相减，换月跳空会在两腿上不同步，制造虚假的价差跳跃。每条腿按各自的交割日历持有对应月份，价差在合约空间里计算，再按规则同时滚仓。</span></p>',26)),(e(),l(m,null,{default:r(()=>[d(o,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20LR%0A%20%20RAW%5B%22%E4%B8%8A%E6%B8%B8%3A%20%E5%8E%9F%E6%B2%B9%20%2F%20%E5%A4%A7%E8%B1%86%20%2F%20%E5%A4%A9%E7%84%B6%E6%B0%94%22%5D%20--%3E%20PROC%5B%22%E4%BA%A7%E8%83%BD%E4%B8%8E%E5%B7%A5%E8%89%BA%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20PROC%20--%3E%20OUT%5B%22%E4%B8%8B%E6%B8%B8%3A%20%E6%88%90%E5%93%81%E6%B2%B9%20%2F%20%E7%B2%95%E6%B2%B9%20%2F%20%E7%94%B5%22%5D%0A%20%20INV%5B%22%E7%9B%B8%E5%AF%B9%E5%BA%93%E5%AD%98%22%5D%20--%3E%20MARG%5B%22%E5%8A%A0%E5%B7%A5%E5%88%A9%E6%B6%A6%22%5D%0A%20%20PROC%20--%3E%20MARG%0A%20%20MARG%20--%3E%20FUT%5B%22%E6%9C%9F%E8%B4%A7%E8%B7%A8%E5%93%81%E7%A7%8D%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20FUT%20--%3E%20EXEC%5B%22%E4%BB%B7%E5%B7%AE%E6%8C%87%E4%BB%A4%20%2F%20%E4%BF%9D%E8%AF%81%E9%87%91%E7%BB%84%E5%90%88%22%5D%0A%20%20BRK%5B%22%E5%B7%A5%E8%89%BA%E6%88%96%E6%94%BF%E7%AD%96%E6%96%AD%E7%82%B9%22%5D%20--%3E%20PROC%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跨品种价差应以实物单位（裂解、压榨、火花、地点）定义权重，而不是以样本内回归 beta 定义。</li><li>均值回复的机制是产能与库存响应，不是两道价格偶然协整；相对库存是状态变量。</li><li>执行用交易所组合或 EFP，腿间时滞会把加工利润变成方向性原油（或大豆）暴露。</li><li>工艺、规格与出口制度会造成协整断点；断点后应重估约束，而不是只重估统计阈值。</li><li>凯恩斯—希克斯溢价若要引入，应作为相对套保压力的二阶项，并服从库存能否预测这一检验。</li><li>出处：Working, <em>AER</em>, 1949；Geman, <em>Commodities and Commodity Derivatives</em>, 2005；Gorton and Rouwenhorst, <em>FAJ</em>, 2006；Gorton, Hayashi and Rouwenhorst, <em>Review of Finance</em>, 2013；协整工具见 Engle and Granger, <em>Econometrica</em>, 1987。</li></ul>',2))])}const T=n(h,[["render",B]]);export{q as __pageData,T as default};
